create table public.branches (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, store_id uuid not null references public.stores(id) on delete cascade, name text not null, code text not null, status text not null default 'active' check (status in ('active','inactive')), created_at timestamptz not null default now(), unique(store_id,code));`ncreate index branches_tenant_idx on public.branches(company_id,store_id);`nalter table public.branches enable row level security;`ncreate policy branches_member_read on public.branches for select using (public.is_company_member(company_id));